#include <bits/stdc++.h>
using namespace std;
#define LL long long
#define loop(i, a, b) for(int i = a; i < b; ++i)

const int MAXN = 500;
int mod_value, c[MAXN + 1][MAXN + 1];
pair<int, int> dp1_arr[MAXN + 1], dp2_arr[2][MAXN + 1][MAXN + 1];

void add_mod(int &a, int b) { if ((a += b) >= mod_value) a -= mod_value; }

int sum_series(int n) { return n * (n + 1) >> 1; }

int main() {
    int n, m;
    scanf("%d%d%d", &n, &m, &mod_value);
    for (int i = 0; i <= m; ++i) {
        c[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            add_mod(c[i][j], c[i - 1][j]);
            add_mod(c[i][j], c[i - 1][j - 1]);
        }
    }
    dp1_arr[0].first = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int w = (long long)dp1_arr[j - 1].first * dp1_arr[i - j].first % mod_value * c[i - 1][j - 1] % mod_value;
            add_mod(dp1_arr[i].second, (sum_series(j - 1) + sum_series(i - j)) * (long long)w % mod_value);
            add_mod(dp1_arr[i].second, (long long)dp1_arr[j - 1].second * dp1_arr[i - j].first % mod_value * (i + 1) % mod_value * c[i - 1][j - 1] % mod_value);
            add_mod(dp1_arr[i].second, (long long)dp1_arr[j - 1].first * dp1_arr[i - j].second % mod_value * (i + 1) % mod_value * c[i - 1][j - 1] % mod_value);
            add_mod(dp1_arr[i].first, (long long)w * (i + 1) % mod_value);
        }
    }
    dp2_arr[0][0][0].first = 1;
    dp2_arr[1][0][0].first = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            for (int ln = 1; ln <= n - i; ++ln) {
                add_mod(dp2_arr[1][i + ln][j].first, dp2_arr[0][i][j].first);
                add_mod(dp2_arr[1][i + ln][j].second, dp2_arr[0][i][j].second);
                add_mod(dp2_arr[0][i + ln][j + ln].first, (long long)dp2_arr[1][i][j].first * dp1_arr[ln].first % mod_value * c[j + ln][j] % mod_value);
                add_mod(dp2_arr[0][i + ln][j + ln].second, (long long)dp2_arr[1][i][j].first * dp1_arr[ln].second % mod_value * c[j + ln][j] % mod_value);
                add_mod(dp2_arr[0][i + ln][j + ln].second, (long long)dp2_arr[1][i][j].second * dp1_arr[ln].first % mod_value * c[j + ln][j] % mod_value);
            }
        }
    }
    int final_ans = dp2_arr[0][n][m].second;
    add_mod(final_ans, dp2_arr[1][n][m].second);
    printf("%d\n", final_ans);
}
